-- Bill splitter schema.
-- All ids are UUID strings generated by the API.
-- `seq` on members records the order in which members were added to a home,
-- which decides who gets the extra cents when a bill does not divide evenly.

CREATE TABLE homes (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL,

  -- Stops empty/whitespace-only home names.
  CONSTRAINT chk_homes_name CHECK (length(trim(name)) > 0)
);

CREATE TABLE members (
  id TEXT PRIMARY KEY,
  home_id TEXT NOT NULL,
  name TEXT NOT NULL,
  -- Unique per home; assignment uses MAX(seq)+1 under the row we insert.
  seq INTEGER NOT NULL,
  created_at TEXT NOT NULL,

  -- A member can only be added to a home that exists.
  CONSTRAINT fk_members_home FOREIGN KEY (home_id) REFERENCES homes (id) ON DELETE CASCADE,
  -- Stops two members of the same home from grabbing the same position in the
  -- split order (two concurrent "add member" requests on the same home).
  CONSTRAINT uq_members_home_seq UNIQUE (home_id, seq),
  -- Stops empty/whitespace-only member names.
  CONSTRAINT chk_members_name CHECK (length(trim(name)) > 0)
);

CREATE TABLE bills (
  id TEXT PRIMARY KEY,
  home_id TEXT NOT NULL,
  title TEXT NOT NULL,
  -- Whole cents only. The API also validates this before inserting.
  total_cents INTEGER NOT NULL,
  created_at TEXT NOT NULL,

  -- A bill can only be added to a home that exists.
  CONSTRAINT fk_bills_home FOREIGN KEY (home_id) REFERENCES homes (id) ON DELETE CASCADE,
  -- Stops a zero/negative/non-integer total from ever reaching the database.
  CONSTRAINT chk_bills_total CHECK (
    total_cents > 0
    AND total_cents = CAST(total_cents AS INTEGER)
  ),
  -- Stops empty/whitespace-only bill titles.
  CONSTRAINT chk_bills_title CHECK (length(trim(title)) > 0)
);

CREATE TABLE shares (
  id TEXT PRIMARY KEY,
  bill_id TEXT NOT NULL,
  member_id TEXT NOT NULL,
  amount_cents INTEGER NOT NULL,
  -- ISO timestamp when the share was paid, NULL while unpaid.
  paid_at TEXT,
  -- The Idempotency-Key of the request that paid this share.
  -- Used to repeat the same payment answer and to detect a different key.
  paid_key TEXT,

  -- A share can only be attached to a bill that exists; deleting a bill
  -- deletes its shares with it.
  CONSTRAINT fk_shares_bill FOREIGN KEY (bill_id) REFERENCES bills (id) ON DELETE CASCADE,
  -- A share can only belong to a member of some home; deleting a member
  -- deletes their shares with them.
  CONSTRAINT fk_shares_member FOREIGN KEY (member_id) REFERENCES members (id) ON DELETE CASCADE,
  -- Stops the same member from being charged twice on the same bill.
  CONSTRAINT uq_shares_bill_member UNIQUE (bill_id, member_id),
  -- Stops a negative/non-integer share amount from ever reaching the database.
  -- Zero is allowed on purpose: a bill of 1 cent split between 3 members is
  -- 1, 0, 0 (the shares must always add up to the bill total).
  CONSTRAINT chk_shares_amount CHECK (
    amount_cents >= 0
    AND amount_cents = CAST(amount_cents AS INTEGER)
  )
);

-- Speeds up "list members of a home in the order they were added".
CREATE INDEX idx_members_home_seq ON members (home_id, seq);
-- Speeds up "list bills of a home".
CREATE INDEX idx_bills_home ON bills (home_id);
-- Speeds up "sum unpaid shares of a member".
CREATE INDEX idx_shares_member ON shares (member_id);
